function loadMemories(){try{return JSON.parse(localStorage.getItem(STORE)||"[]")}catch{return[]}}
function saveMemories(){localStorage.setItem(STORE,JSON.stringify(state.memories))}
function saveMapSelection(){localStorage.setItem("jmm_map_selection_v1",JSON.stringify(state.mapSelection))}
function esc(s=""){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function visited(){return new Set(state.memories.map(m=>m.prefectureId))}
function setView(v){state.view=v;state.selectedPref=null;state.selectedMemory=null;render()}
function resetDemo(){localStorage.removeItem(STORE);localStorage.removeItem("jmm_map_selection_v1");state.memories=[];state.mapSelection={};render()}

async function refreshStoredMaskedPhotos(){
 // 地図用の県型画像は代表写真だけ保持し、アルバム写真には重い県型PNGを持たせない。
 // localStorageの容量圧迫を避け、複数枚保存を安定させる。
 const list=state.memories.filter(m=>m.originalPhoto && m.prefectureId);
 let changed=false;
 for(const m of list){
   try{
     if(m.photoRole==='album'){
       if(m.maskedPhoto){ delete m.maskedPhoto; changed=true; }
       continue;
     }
     const blobData=await dataUrlToBlob(m.originalPhoto);
     const file=new File([blobData], "memory.jpg", {type:blobData.type||"image/jpeg"});
     const result=await makeMasked(file,m.prefectureId);
     if(result?.masked && m.maskedPhoto!==result.masked){m.maskedPhoto=result.masked;changed=true;}
   }catch(err){
     console.warn("PHOTO_RECLIP_FAIL",m.id,err);
   }
 }
 if(changed){ try{ saveMemories(); }catch(err){ console.warn("PHOTO_COMPACT_SAVE_FAIL",err); } }
}
function dataUrlToBlob(dataUrl){
 return fetch(dataUrl).then(r=>r.blob());
}
async function boot(){
 state.geo=EMBEDDED_GEOMETRY;
 state.prefectureGroups={};
 try{
   const doc=new DOMParser().parseFromString(EMBEDDED_SVG,"image/svg+xml");
   doc.querySelectorAll("[data-code]").forEach(g=>{
     const id=String(g.getAttribute("data-code")).padStart(2,"0");
     const clone=g.cloneNode(true);
     clone.removeAttribute("data-code");
     clone.removeAttribute("onclick");
     clone.removeAttribute("onkeydown");
     clone.removeAttribute("role");
     clone.removeAttribute("tabindex");
     state.prefectureGroups[id]=new XMLSerializer().serializeToString(clone);
   });
 }catch(e){console.warn("SVG_GROUP_PARSE_FAIL",e);}
 render();
 try{
   await refreshStoredMaskedPhotos();
   if(state.view==="map") render();
 }catch(e){console.warn("PHOTO_MIGRATION_FAIL",e);}
}
function nav(active){
 return `<nav class="bottom-nav">
  <button class="nav-item ${active==="map"?"active":""}" onclick="setView('map')"><span class="nav-icon">⌖</span>マップ</button>
  <button class="nav-item ${active==="memories"?"active":""}" onclick="setView('memories')"><span class="nav-icon">▤</span>思い出一覧</button>
  <button class="add-nav" onclick="setView('add')" aria-label="思い出を追加">＋</button>
  <button class="nav-item ${active==="prefectures"?"active":""}" onclick="setView('prefectures')"><span class="nav-icon">▦</span>都道府県</button>
  <button class="nav-item ${active==="profile"?"active":""}" onclick="setView('profile')"><span class="nav-icon">♙</span>マイページ</button>
 </nav>`
}
function shell(content,active="map"){
 return `<div class="app-shell"><div class="container">${content}</div>${nav(active)}</div>`
}
function render(){
 document.querySelectorAll(".modal-backdrop").forEach(el=>el.remove());
 const root=document.getElementById("app");
 if(!state.user && state.view!=="signup"){root.innerHTML=authView();return}
 if(state.view==="map")root.innerHTML=shell(mapView(),"map");
 if(state.view==="memories")root.innerHTML=shell(memoriesView(),"memories");
 if(state.view==="prefectures")root.innerHTML=shell(prefecturesView(),"prefectures");
 if(state.view==="profile")root.innerHTML=shell(profileView(),"profile");
 if(state.view==="add")root.innerHTML=shell(addView(),"");
 if(state.view==="settings")root.innerHTML=shell(settingsView(),"profile");
 if(state.selectedPref)openPrefSheet(state.selectedPref);
 if(state.selectedMemory)openMemorySheet(state.selectedMemory);
}
