function recentMemoryGroups(items){
 const groups=[]; const index=new Map();
 for(const m of items){ const name=(m.title||'無題の思い出').trim()||'無題の思い出'; if(!index.has(name)){index.set(name,groups.length);groups.push({name,items:[]})} groups[index.get(name)].items.push(m); }
 return groups;
}
function openRecentFolder(name){
 const ms=state.memories.filter(m=>(m.title||'無題の思い出').trim()===(name||'').trim());
 if(ms.length<=1){ if(ms[0]){state.selectedMemory=ms[0].id;render()} return; }
 const el=document.createElement('div'); el.className='modal-backdrop'; el.onclick=e=>{if(e.target===el)e.currentTarget.remove()};
 el.innerHTML=`<section class="sheet photo-album-sheet">
   <div class="sheet-head"><div><div class="kicker">RECENT / PHOTO FOLDER</div><h2>${esc(name)}</h2><p class="page-subtitle">${ms.length}枚の写真</p></div><button class="close" onclick="this.closest('.modal-backdrop').remove()">×</button></div>
   <div class="album-grid">${ms.map(m=>`<button class="album-photo" onclick="this.closest('.modal-backdrop').remove();state.selectedMemory='${m.id}';render()"><img src="${m.originalPhoto||m.maskedPhoto}" alt="${esc(m.title)}"><strong>${esc(NAMES[m.prefectureId])}</strong><small>${esc(m.visitDate)}</small></button>`).join('')}</div>
 </section>`;
 document.body.appendChild(el);
}
function openAddPrefChooser(){
 const el=document.createElement('div'); el.className='modal-backdrop'; el.onclick=e=>{if(e.target===el)e.currentTarget.remove()};
 el.innerHTML=`<section class="sheet pref-add-sheet"><div class="sheet-head"><div><div class="kicker">NEW MEMORY</div><h2>投稿する県を選ぶ</h2><p class="page-subtitle">県を選んでから写真をまとめて追加できます。</p></div><button class="close" onclick="this.closest('.modal-backdrop').remove()">×</button></div>
 <div class="pref-choice-grid">${Object.entries(NAMES).map(([id,n])=>`<button type="button" onclick="this.closest('.modal-backdrop').remove();startAdd('gallery','${id}')"><span>${id}</span><strong>${n}</strong></button>`).join('')}</div></section>`;
 document.body.appendChild(el);
}
function getPhotoGroups(){
 const groups={};
 for(const m of state.memories){
   if(!m.originalPhoto) continue;
   (groups[m.prefectureId] ||= []).push(m);
 }
 return groups;
}
function openExtraPhotoChooser(){
 const groups=getPhotoGroups();
 const multi=Object.entries(groups).filter(([,ms])=>ms.length>1);
 const el=document.createElement('div');
 el.className='modal-backdrop';
 el.onclick=e=>{if(e.target===el)el.remove()};
 el.innerHTML=`<section class="sheet photo-chooser-sheet">
   <div class="sheet-head"><div><div class="kicker">PHOTO ALBUM</div><h2>県を選ぶ</h2><p class="page-subtitle">複数写真を登録した県から選択できます。</p></div><button class="close" onclick="this.closest('.modal-backdrop').remove()">×</button></div>
   ${multi.length?`<div class="pref-photo-list">${multi.map(([pref,ms])=>`<button class="pref-photo-choice" onclick="openMapPhotoPeek('${pref}',this.closest('.modal-backdrop'))"><span class="pref-photo-thumb"><img src="${ms[0].originalPhoto}" alt=""></span><span><strong>${NAMES[pref]}</strong><small>${ms.length}枚の写真</small></span><b>›</b></button>`).join('')}</div>`:`<div class="empty chooser-empty"><h2>まだ複数写真の県がありません</h2><p>「＋」から1回の登録で2枚以上の写真を追加すると、ここから見られます。</p><button class="primary" onclick="this.closest('.modal-backdrop').remove();startAdd('gallery')">写真を追加する</button></div>`}
 </section>`;
 document.body.appendChild(el);
}
function openMapPhotoPeek(pref,chooser){
 if(chooser)chooser.remove();
 const pid=String(pref).padStart(2,"0");
 const ms=state.memories.filter(m=>m.prefectureId===pid && m.originalPhoto);
 if(ms.length<2){ openExtraPhotos(pid); return; }
 // 地図を見ながら右下で「ほかの写真」を覗ける。常時表示はしない。
 const old=document.querySelector('.map-photo-peek'); if(old)old.remove();
 const el=document.createElement('div');
 el.className='map-photo-peek';
 el.innerHTML=`<div class="map-photo-peek-head"><div><span>PHOTO</span><strong>${NAMES[pid]}</strong></div><button type="button" aria-label="閉じる" onclick="this.closest('.map-photo-peek').remove()">×</button></div>
   <div class="map-photo-peek-strip">${ms.slice(0,4).map(m=>`<button class="map-photo-peek-item" type="button" onclick="openMemorySheet('${m.id}')"><img src="${m.originalPhoto||m.maskedPhoto}" alt="${esc(m.title)}"></button>`).join('')}</div>
   <button class="map-photo-peek-more" type="button" onclick="openExtraPhotos('${pid}');this.closest('.map-photo-peek').remove()">すべての写真を見る <b>›</b></button>`;
 const stage=document.querySelector('.map-stage');
 if(stage && window.matchMedia && window.matchMedia('(max-width: 520px)').matches && stage.parentElement){
   stage.parentElement.appendChild(el);
 }else{
   stage?.appendChild(el);
 }
}
function albumGroups(ms){
 const groups=[]; const index=new Map();
 for(const m of ms){ const name=(m.title||'無題の思い出').trim()||'無題の思い出'; if(!index.has(name)){index.set(name,groups.length);groups.push({name,items:[]})} groups[index.get(name)].items.push(m); }
 return groups;
}
