let currentPreview=null;
async function previewExistingSelection(){
 const pref=document.getElementById("pref")?.value;
 if(selectedFiles.length && pref) await rebuildPhotoPreviews();
}
async function refreshPreviewAfterPrefChange(){ await previewExistingSelection(); }
function handlePhotoFiles(e){
 const files=Array.from(e.target.files||[]);
 if(!files.length)return;
 const valid=[];
 for(const file of files){
   if(!/^image\/(jpeg|png|webp|heic|heif|avif)$/i.test(file.type||"")){alert("画像ファイルを選択してください");continue}
   if(file.size>10*1024*1024){alert(`${file.name} は10MBを超えているため追加できません。`);continue}
   valid.push(file);
 }
 const seen=new Set(selectedFiles.map(f=>`${f.name}|${f.size}|${f.lastModified}`));
 for(const file of valid){const key=`${file.name}|${file.size}|${file.lastModified}`;if(!seen.has(key)){selectedFiles.push(file);seen.add(key)}}
 e.target.value="";
 updateSelectedPhotoUI();
 if(document.getElementById("pref")?.value) rebuildPhotoPreviews();
}
function removeSelectedFile(index){ selectedFiles.splice(index,1); updateSelectedPhotoUI(); rebuildPhotoPreviews(); }
function updateSelectedPhotoUI(){
 const count=document.getElementById("selectedPhotoCount");
 if(count) count.textContent=selectedFiles.length?`${selectedFiles.length}枚を選択中${selectedFiles.length>1?"（最初の1枚が地図に反映されます）":""}`:"写真を選択してください";
 const submit=document.querySelector('.form-submit-row .primary');
 if(submit){ submit.textContent=selectedFiles.length>1?`${selectedFiles.length}枚を保存する`:"県型写真を作って保存"; submit.disabled=!selectedFiles.length; }
}
async function rebuildPhotoPreviews(){
 const pref=document.getElementById("pref")?.value;
 const area=document.getElementById("previewArea");
 if(!area)return;
 if(!selectedFiles.length){area.innerHTML="";currentPreviews=[];currentPreview=null;return}
 if(!pref){area.innerHTML=`<div class="notice">都道府県を選択すると、写真が県の形に切り抜かれます。</div>`;return}
 area.innerHTML=`<div class="preview"><div class="kicker">${NAMES[pref]} SHAPE PREVIEW</div><div class="preview-grid">${selectedFiles.map((_,i)=>`<div class="preview-item" id="preview-item-${i}"><div class="preview-loading">処理中…</div></div>`).join("")}</div><p class="small">${selectedFiles.length>1?"最初に選んだ1枚が地図に反映されます。その他の写真は県ごとのフォトアルバムに保存されます。":"この形で日本地図に表示されます。"}</p></div>`;
 const previews=[];
 for(let i=0;i<selectedFiles.length;i++){
   try{
     const result=await makeMasked(selectedFiles[i],pref); previews.push(result);
     const item=document.getElementById(`preview-item-${i}`);
     if(item)item.innerHTML=`<img src="${result.masked}" alt="${NAMES[pref]}の県型プレビュー"><button type="button" class="preview-remove" onclick="removeSelectedFile(${i})">×</button><small>${esc(selectedFiles[i].name)}</small>`;
   }catch(err){
     const item=document.getElementById(`preview-item-${i}`); if(item)item.innerHTML=`<div class="error">この写真の処理に失敗しました。</div>`;
     throw err;
   }
 }
 currentPreviews=previews; currentPreview=previews[0]||null;
}
async function previewFile(e){ handlePhotoFiles(e); }

async function makeMasked(file,pref){
 pref=String(pref).padStart(2,"0");
 const src=await fileToDataURL(file);
 const img=await loadImage(src);
 const shapeSrc=PREFECTURE_SHAPES[pref];
 const geo=state.geo?.[pref];
 if(!shapeSrc || !geo) throw new Error("PREFECTURE_SHAPE_NOT_FOUND");

 // 地図と同じ1000x1000座標系に写真を配置。
 const canvas=document.createElement("canvas");
 canvas.width=1000; canvas.height=1000;
 const ctx=canvas.getContext("2d");
 const scale=Math.max(geo.w/img.width,geo.h/img.height);
 const dw=img.width*scale, dh=img.height*scale;
 const dx=geo.x+(geo.w-dw)/2, dy=geo.y+(geo.h-dh)/2;
 ctx.drawImage(img,dx,dy,dw,dh);

 // 保存した「その県の正確なSVG形状」をアルファマスクとして適用。
 const shape=await loadImage(shapeSrc);
 ctx.globalCompositeOperation="destination-in";
 ctx.drawImage(shape,0,0,1000,1000);
 ctx.globalCompositeOperation="source-over";

 // 県外は透明のまま。地図の背景色が下から見える。
 return {masked:canvas.toDataURL("image/png"),original:src};
}

function fileToDataURL(file){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)})}
function loadImage(src){return new Promise((res,rej)=>{const i=new Image();i.onload=()=>res(i);i.onerror=rej;i.src=src})}
async function compressPhotoForStorage(dataUrl,maxSide=720,quality=.45){
 const img=await loadImage(dataUrl);
 const scale=Math.min(1,maxSide/Math.max(img.width,img.height));
 const w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale));
 const canvas=document.createElement("canvas"); canvas.width=w; canvas.height=h;
 const ctx=canvas.getContext("2d"); ctx.drawImage(img,0,0,w,h);
 return canvas.toDataURL("image/jpeg",quality);
}
async function compactMemoriesForStorage(maxSide=720,quality=.45){
 // 地図に実際に表示している写真だけ県型PNGを残し、アルバム写真は軽量JPEGに統一。
 for(const m of state.memories){
   if(m.originalPhoto){
     try{ m.originalPhoto=await compressPhotoForStorage(m.originalPhoto,maxSide,quality); }catch{}
   }
   const selected=state.mapSelection?.[m.prefectureId]===m.id;
   if(!selected) delete m.maskedPhoto;
 }
}
async function persistMemoriesSafely(){
 try{ saveMemories(); return true; }catch(firstErr){
   // まず現在データを軽量化してから再試行。既存機能は維持する。
   await compactMemoriesForStorage(600,.38);
   try{ saveMemories(); return true; }catch(secondErr){
     await compactMemoriesForStorage(480,.30);
     try{ saveMemories(); return true; }catch(finalErr){
       console.error("MEMORY_STORAGE_QUOTA",finalErr);
       return false;
     }
   }
 }
}
async function createMemory(e){
 e.preventDefault();
 const btn=document.getElementById("saveMemoryBtn");
 const pref=document.getElementById("pref")?.value;
 if(!pref){alert("都道府県を選択してください");return}
 if(!selectedFiles.length){alert("写真を1枚以上選択してください");return}
 if(btn){btn.disabled=true;btn.dataset.originalText=btn.textContent;btn.textContent="保存しています…";}
 let persisted=false;
 let createdCount=0;
 try{
   if(currentPreviews.length!==selectedFiles.length) await rebuildPhotoPreviews();
   if(currentPreviews.length!==selectedFiles.length) throw new Error("PHOTO_PREVIEW_COUNT_MISMATCH");
   const base={prefectureId:pref,visitDate:document.getElementById("date").value,title:document.getElementById("title").value.trim(),category:document.getElementById("cat").value,location:document.getElementById("place").value.trim()||null,description:document.getElementById("desc").value.trim()||null};
   if(!base.visitDate||!base.title||!base.category) throw new Error("REQUIRED_FIELD_MISSING");
   const batchId=crypto.randomUUID();
   // 複数写真は保存容量を抑え、地図用の県型PNGは代表写真1枚だけ保持する。
   const storedOriginals=await Promise.all(currentPreviews.map(preview=>compressPhotoForStorage(preview.original,720,.45)));
   const created=currentPreviews.map((preview,i)=>({id:crypto.randomUUID(),...base,originalPhoto:storedOriginals[i],maskedPhoto:i===0?preview.masked:null,createdAt:new Date().toISOString(),batchId,albumKey:`pref-${pref}`,photoRole:i===0?'map':'album',batchIndex:i+1}));
   createdCount=created.length;
   const firstCreatedId=created[0].id;
   state.memories.unshift(...created.slice().reverse());
   state.mapSelection[pref]=firstCreatedId;
   persisted=await persistMemoriesSafely();
   if(!persisted) throw new Error("MEMORY_STORAGE_QUOTA");
   try{ saveMapSelection(); }catch(mapErr){ console.warn("MAP_SELECTION_SAVE_FAIL",mapErr); }
   selectedFiles=[];currentPreviews=[];currentPreview=null;prefillPref="";
   try{ setView("map"); }catch(renderErr){ console.warn("MAP_RENDER_AFTER_SAVE_FAIL",renderErr); }
   setTimeout(()=>showToast(`${createdCount}枚の写真を保存しました`),50);
 }catch(err){
   console.error("MEMORY_CREATE_FAIL",err);
   if(btn){btn.disabled=false;btn.textContent=btn.dataset.originalText||"県型写真を作って保存";}
   // 保存データが確定した後の画面更新エラーでは「保存失敗」と誤表示しない。
   if(persisted){
     setTimeout(()=>showToast(`${createdCount}枚の写真を保存しました`),50);
     try{ setView("map"); }catch{}
     return;
   }
   const message=err?.message==="REQUIRED_FIELD_MISSING"?"必須項目を入力してください。":"写真を保存できませんでした。写真の枚数を減らしてもう一度お試しください。";
   alert(message);
 }
}
function showToast(message){
 const old=document.querySelector(".jmm-toast"); if(old) old.remove();
 const el=document.createElement("div"); el.className="jmm-toast"; el.textContent=message; document.body.appendChild(el);
 requestAnimationFrame(()=>el.classList.add("show"));
 setTimeout(()=>{el.classList.remove("show");setTimeout(()=>el.remove(),250)},2200);
}

function openMemorySheet(id){
 const m=state.memories.find(x=>x.id===id); if(!m)return;
 const el=document.createElement("div");el.className="modal-backdrop";el.onclick=e=>{if(e.target===el){state.selectedMemory=null;render()}}
 el.innerHTML=`<section class="sheet"><div class="sheet-head"><div><div class="kicker">${NAMES[m.prefectureId]}</div><h2>${esc(m.title)}</h2></div><button class="close" onclick="state.selectedMemory=null;render()">×</button></div>
 <img class="detail-photo" src="${m.originalPhoto||m.maskedPhoto}" alt="">
 <div class="meta" style="margin:14px 0">${esc(m.visitDate)} ・ ${esc(m.category)}${m.location?" ・ "+esc(m.location):""}</div>
 ${m.description?`<p style="line-height:1.9">${esc(m.description)}</p>`:""}
 <div class="cta-row" style="justify-content:flex-start"><button class="primary" onclick="showPhotoOnMap('${m.id}')">この写真を地図に表示</button><button class="secondary" onclick="deleteMemory('${m.id}')">削除</button></div></section>`;
 document.body.appendChild(el)
}
async function showPhotoOnMap(id){
 const m=state.memories.find(x=>x.id===id);
 if(!m) return;
 const btn=event?.currentTarget;
 if(btn){btn.disabled=true;btn.dataset.originalText=btn.textContent;btn.textContent="地図に反映しています…";}
 try{
   // 2枚目以降には地図用の県型PNGを保持していないため、選択時に生成する。
   if(!m.maskedPhoto && m.originalPhoto){
     const blob=await dataUrlToBlob(m.originalPhoto);
     const file=new File([blob],"memory.jpg",{type:blob.type||"image/jpeg"});
     const result=await makeMasked(file,m.prefectureId);
     m.maskedPhoto=result.masked;
     saveMemories();
   }
   if(!m.maskedPhoto) throw new Error("MAP_PHOTO_GENERATE_FAIL");
   state.mapSelection[m.prefectureId]=m.id;
   saveMapSelection();
   state.selectedMemory=null;
   state.selectedPref=null;
   setView("map");
   setTimeout(()=>showToast("この写真を地図に表示しました"),50);
 }catch(err){
   console.error("MAP_PHOTO_SELECT_FAIL",err);
   if(btn){btn.disabled=false;btn.textContent=btn.dataset.originalText||"この写真を地図に表示";}
   alert("この写真を地図に表示できませんでした。もう一度お試しください。");
 }
}

function editMemory(id){
 const m=state.memories.find(x=>x.id===id);if(!m)return;state.selectedMemory=null;state.editing=m;renderEdit()
}
function renderEdit(){
 const m=state.editing;
 document.getElementById("app").innerHTML=`<div class="app-shell"><div class="container"><header class="topbar"><div><div class="kicker">EDIT MEMORY</div><h2>思い出を編集</h2></div><button class="icon-btn" onclick="state.editing=null;setView('memories')">×</button></header>
 <section class="form-card"><div class="form-grid">
 <div class="field"><label>都道府県 *</label><select id="epref">${Object.entries(NAMES).map(([id,n])=>`<option value="${id}" ${id===m.prefectureId?"selected":""}>${n}</option>`).join("")}</select></div>
 <div class="field"><label>訪問日 *</label><input id="edate" type="date" value="${esc(m.visitDate)}"></div>
 <div class="field"><label>タイトル *</label><input id="etitle" value="${esc(m.title)}"></div>
 <div class="field"><label>カテゴリ *</label><select id="ecat">${CATS.map(c=>`<option ${c===m.category?"selected":""}>${c}</option>`).join("")}</select></div>
 <div class="field"><label>場所（任意）</label><input id="eplace" value="${esc(m.location||"")}"></div>
 <div class="field"><label>説明文（任意）</label><textarea id="edesc" rows="4">${esc(m.description||"")}</textarea></div>
 </div><div class="cta-row"><button class="primary" onclick="saveEdit()">保存する</button></div></section></div></div>`
}
async function saveEdit(){
 const m=state.editing;
 const oldPref=m.prefectureId;
 const newPref=String(document.getElementById("epref").value).padStart(2,"0");
 const next={prefectureId:newPref,visitDate:document.getElementById("edate").value,title:document.getElementById("etitle").value.trim(),category:document.getElementById("ecat").value,location:document.getElementById("eplace").value.trim()||null,description:document.getElementById("edesc").value.trim()||null};
 if(!next.visitDate||!next.title||!next.category||!newPref){alert("必須項目を入力してください。");return}
 if(oldPref!==newPref && m.originalPhoto){
   try{
     const blob=await dataUrlToBlob(m.originalPhoto);
     const file=new File([blob],"memory.jpg",{type:blob.type||"image/jpeg"});
     const result=await makeMasked(file,newPref);
     m.maskedPhoto=result.masked;
   }catch(err){alert("県型写真の再生成に失敗しました。写真は変更されていません。");return}
 }
 Object.assign(m,next);
 if(oldPref!==newPref && state.mapSelection?.[oldPref]===m.id) delete state.mapSelection[oldPref];
 state.mapSelection[newPref]=m.id;
 saveMemories();saveMapSelection();state.editing=null;setView("memories")
}

function deleteMemory(id){
 if(!confirm("この思い出を削除しますか？"))return;
 const target=state.memories.find(m=>m.id===id);
 if(!target)return;
 const prev=state.memories;
 state.memories=state.memories.filter(m=>m.id!==id);
 if(state.mapSelection?.[target.prefectureId]===id){
   const replacement=state.memories.find(m=>m.prefectureId===target.prefectureId && m.originalPhoto);
   if(replacement) state.mapSelection[target.prefectureId]=replacement.id;
   else delete state.mapSelection[target.prefectureId];
 }
 try{
   saveMemories(); saveMapSelection(); state.selectedMemory=null; render(); showToast("写真を削除しました");
 }catch(err){
   console.error("MEMORY_DELETE_FAIL",err);
   state.memories=prev;
   alert("写真の削除を保存できませんでした。もう一度お試しください。");
 }
}
function logout(){localStorage.removeItem(USER);state.user=null;render()}
function showAbout(){
 alert("JAPAN MEMORY MAP\\n\\n写真を都道府県の形に切り抜き、日本地図に残す思い出マップです。\\n\\n現在はブラウザ内保存で動くMVPデモです。")
}
boot()
